/**
 * A job with a recorded notice that still owes one (punch list #353, part 2). Pure.
 *
 * A § 53.056 notice recorded by hand for several jobs at a property names the paper's months. A job whose last work
 * month is later, from a last day of work set by hand, still owes that month's notice, and the desk is right to keep it
 * in To draft. But the row gave no reason, so the office, who had just recorded the mailing and its receipt, expected
 * the row to clear. And the affidavit pane let a draft through while the last work month's own notice was still due.
 * Three readers say it now: the To do row names the owed month beside the months the notice on record names, the
 * affidavit pane says the last work month's notice is still due above *Send for approval*, and the dev seat's
 * `plan_affidavit_draft` carries the same line. A line, never a gate: the owner and the attorney decide the paper.
 */

/** The To do row's words when a notice is on record and a month still owes one: the owed months, then the record's. Null with no notice on record, or nothing owed. */
export function lienNoticeOwedWords(dueMonths: ReadonlyArray<string>, namedMonths: ReadonlyArray<string>): string | null {
  const owed = [...new Set(dueMonths.filter((m) => /^\d{4}-\d{2}$/.test(m)))].sort()
  const named = [...new Set(namedMonths.filter((m) => /^\d{4}-\d{2}$/.test(m)))].sort()
  if (owed.length === 0 || named.length === 0) return null
  return `${describeNoticeMonths(owed)} ${owed.length === 1 ? 'has' : 'have'} no notice. The one on record names ${noticeMonthsSpanWords(named)}.`
}

/** The months the live § 53.056 notices name on a job, for the row: `lienAffidavitNoticeMonths` under its own name. */
export function lienNoticeNamedMonths(filings: ReadonlyArray<LienAffidavitNoticeRow> | null | undefined): string[] {
  return lienAffidavitNoticeMonths(filings)
}

/** The three doors a To do row offers beside the owed month (the owner's picks of 2026-11-14), in the row's own words. */
export const LIEN_NOTICE_OWED_DOORS = {
  /** The paper as mailed named the owed month too: the record is corrected, and the row clears. */
  named: (months: ReadonlyArray<string>) => `The paper named ${describeNoticeMonths(months)} too`,
  /** The last day of work is wrong: the Lien window opens with the day ready to change. */
  lastDay: 'The last day of work is wrong',
} as const

/** The owed months a row's door would add to the recorded notice: the ones due now, as the row named them. */
export function lienNoticeOwedMonths(entry: Pick<LienDeskEntry, 'dueMonths'>): string[] {
  return [...new Set(entry.dueMonths.filter((m) => /^\d{4}-\d{2}$/.test(m)))].sort()
}

export type LienLastMonthNoticeDue = { month: string; dueOn: string }

/**
 * Whether the last work month's own § 53.056 notice is still due on a sub job: no live notice names it, and its window
 * has not closed. Null on a job contracted with the owner, with no last month, when a notice names the month, or once
 * the window has closed (then the late notice is the clock's own story).
 */
export function lienLastMonthNoticeDue(f: { isSub: boolean; lastMonth: string | null | undefined; propertyKind: string | null | undefined; filings: ReadonlyArray<LienAffidavitNoticeRow> | null | undefined; todayYmd: string }): LienLastMonthNoticeDue | null {
  const month = (f.lastMonth ?? '').slice(0, 7)
  if (!f.isSub || !/^\d{4}-\d{2}$/.test(month)) return null
  if (lienAffidavitNoticeMonths(f.filings).includes(month)) return null
  const dueOn = noticeDeadlineForMonth(`${month}-01`, f.propertyKind ?? '')
  if (!dueOn || dueOn < f.todayYmd) return null
  return { month, dueOn }
}

/** The affidavit pane's line above *Send for approval*, and the dev seat's `notice_still_due`: a line, not a gate. */
export function lienAffidavitNoticeDueLine(due: LienLastMonthNoticeDue, formatDay: (ymd: string) => string): string {
  return `${describeNoticeMonths([due.month])}'s notice is still due, by ${formatDay(due.dueOn)}. The paper names that month from the last day on site. Record the notice, and the month has one behind it.`
}

/** A recorded notice, as much of it as the record's correction reads. */
export type LienNoticeToExtend = { id: string; kind: string; months_covered?: ReadonlyArray<string> | null; voided_at?: string | null; created_at?: string | null }

/** The notice the *paper named it too* door corrects: the newest live § 53.056 notice on the job; null with none. */
export function lienNoticeToExtend<F extends LienNoticeToExtend>(filings: ReadonlyArray<F> | null | undefined): F | null {
  const live = (filings ?? []).filter((f) => f.kind === 'notice_53_056' && !f.voided_at)
  if (live.length === 0) return null
  return live.slice().sort((a, b) => ((a.created_at ?? '') < (b.created_at ?? '') ? 1 : -1))[0] ?? null
}

/** The notice's months with the owed ones added, each once, oldest first: what the correction writes to `months_covered`. */
export function lienNoticeMonthsAfter(filing: Pick<LienNoticeToExtend, 'months_covered'>, months: ReadonlyArray<string>): string[] {
  return [...new Set([...(filing.months_covered ?? []), ...months].filter((m) => /^\d{4}-\d{2}$/.test(m)))].sort()
}

/** The confirm window's words for the correction: what it says, and the press that carries the verb. */
export function lienNoticeOwedConfirmWords(months: ReadonlyArray<string>, noticeMonths: ReadonlyArray<string>): { title: string; message: string; confirmLabel: string } {
  const owed = describeNoticeMonths(months)
  return {
    title: `The paper named ${owed} too?`,
    message: `The notice on record names ${describeNoticeMonths(noticeMonths)}. This adds ${owed} to its record, and the row clears. Only if the paper as mailed named ${months.length === 1 ? 'it' : 'them'}.`,
    confirmLabel: `Add ${owed} to the record`,
  }
}
